<section class="panel"><div class="panel-head"><div><span class="section-kicker"><?=e(le_text('LUDZIE TWORZĄ TO MIEJSCE'))?></span><h2><?=e(le_text('Użytkownicy'))?></h2><p><?=e(le_text('Zarządzaj rangami i dostępem do serwisu.'))?></p></div><span class="counter"><?=$listing['total']?> <?=e(le_text('kont'))?></span></div><?php require __DIR__.'/list-controls.php'; ?>
<div class="table-wrap"><table><thead><tr><th><?=e(le_text('Użytkownik'))?></th><th><?=e(le_text('Ochrona konta'))?></th><th><?=e(le_text('Ranga i status'))?></th></tr></thead><tbody><?php foreach($listing['rows'] as $u):?><tr><td><div class="table-user"><div class="user-dot" style="--c:<?=e(valid_hex($u['role_color']))?>"><?=e(mb_strtoupper(mb_substr($u['username'],0,1)))?></div><div><b><?=e($u['username'])?></b><small><?=e($u['email'])?></small><?php if($u['id']==$admin['id']):?><small><?=e(le_text('To Ty'))?></small><?php endif;?></div></div></td><td><span class="status <?=$u['twofa_enabled']?'ok':'draft'?>">2FA <?=$u['twofa_enabled']?le_text('włączone'):le_text('wyłączone')?></span><small><?=e(le_text(!empty($u['email_verified_at'])?'E-mail potwierdzony':'E-mail niepotwierdzony'))?></small></td><td><form method="post" class="user-role-form"><?=csrf_field()?><input type="hidden" name="action" value="user_update"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><label><span class="sr-only"><?=e(le_text('Ranga'))?></span><select class="input compact" name="role_id" <?=$u['id']==$admin['id']?'disabled':''?>><?php foreach($roles as $r):?><option value="<?=(int)$r['id']?>" <?=$u['role_id']==$r['id']?'selected':''?>><?=e($r['name'])?></option><?php endforeach;?></select></label><label><span class="sr-only"><?=e(le_text('Status'))?></span><select class="input compact" name="status" <?=$u['id']==$admin['id']?'disabled':''?>><?php foreach(['active'=>'Aktywne','banned'=>'Zablokowane'] as $status=>$label):?><option value="<?=$status?>" <?=$u['status']===$status?'selected':''?>><?=e(le_text($label))?></option><?php endforeach;?></select></label><?php if($u['id']!=$admin['id']):?><button class="btn" type="submit"><?=e(le_text('Zapisz'))?></button><?php endif;?></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/list-pagination.php'; ?></section>
